const DashboardCard = ({ title, action, children, className = "", delay = 0, onClick }) => (
    <div
        className={`bg-white rounded-xl border border-slate-100 shadow-[0_2px_15px_-3px_rgba(0,0,0,0.07)] flex flex-col relative overflow-hidden group ${className} ${onClick ? 'cursor-pointer' : ''}`}
        style={{ animation: `fadeInUp 0.6s ease-out ${delay}ms forwards`, opacity: 0 }}
        onClick={onClick}
    >
        {(title || action) && (
            <div className="px-6 py-5 border-b border-slate-50 flex items-center justify-between bg-white/50 backdrop-blur-sm z-10">
                {title && <h3 className="font-extrabold text-slate-800 text-sm uppercase tracking-wide">{title}</h3>}
                {action && <div>{action}</div>}
            </div>
        )}
        <div className="p-6 flex-1 min-h-0 relative w-full h-full z-0">
            {children}
        </div>
    </div>
);

const StatCard = ({ title, value, sub, color, icon, delay = 0, onClick }) => {
    // Ensure value is a number for the hook, or handle string fallback
    const numValue = typeof value === 'number' ? value : parseInt(value) || 0;
    const displayValue = useCountUp(numValue);
    const isString = typeof value === 'string' && isNaN(parseInt(value));

    return (
        <div
            className={`bg-white rounded-xl p-5 border border-slate-100 shadow-[0_2px_10px_-4px_rgba(6,81,237,0.1)] ease-out group relative overflow-hidden ${onClick ? 'cursor-pointer' : ''}`}
            style={{ animation: `fadeInUp 0.6s ease-out ${delay}ms forwards`, opacity: 0, transform: 'translateY(10px)' }}
            onClick={onClick}
        >
            <div className="flex justify-between items-start z-10 relative">
                <div>
                    <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">{title}</div>
                    <div className="text-3xl font-black text-slate-800 tracking-tight mt-2">
                        {isString ? value : displayValue.toLocaleString()}
                    </div>
                    {sub && <div className="text-xs text-slate-400 mt-2 font-medium flex items-center gap-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-slate-300"></span> {sub}
                    </div>}
                </div>
                <div
                    className="p-3 rounded-xl text-white shadow-lg transform group-hover:rotate-12 transition-transform duration-500"
                    style={{ background: `linear-gradient(135deg, ${color}, ${adjustColor(color, -20)})` }}
                >
                    {icon}
                </div>
            </div>
            {/* Decorative Blob */}
            <div
                className="absolute -bottom-6 -right-6 w-32 h-32 rounded-full opacity-10 group-hover:scale-110 transition-transform duration-700"
                style={{ backgroundColor: color }}
            ></div>
        </div>
    );
};

